#include "ufbx.h"
#include <stdio.h>
#include <string.h>
int main(int argc,char**argv){ufbx_load_opts o={0};o.ignore_geometry=true;o.load_external_files=false;o.target_axes=ufbx_axes_right_handed_z_up;o.target_unit_meters=1;ufbx_error e;ufbx_scene*s=ufbx_load_file(argv[1],&o,&e);if(!s)return 2;printf("POSES %zu CLUSTERS %zu UNIT %g FPS %g\n",s->poses.count,s->skin_clusters.count,s->settings.unit_meters,s->settings.frames_per_second);for(int f=-1;f<3;f++){ufbx_scene*t=f<0?s:ufbx_evaluate_scene(s,s->anim_stacks.data[0]->anim,f*1.0,NULL,&e);printf("FRAME %d\n",f);for(size_t i=0;i<t->nodes.count;i++){ufbx_node*n=t->nodes.data[i];if(!strcmp(n->name.data,"Root")||!strcmp(n->name.data,"Trajectory")||!strcmp(n->name.data,"Mesh1")||!strcmp(n->name.data,"Pelvis")||!strcmp(n->name.data,"Head")||!strcmp(n->name.data,"L_Ankle")||!strcmp(n->name.data,"L_Hand")||!strcmp(n->name.data,"L_Wrist"))printf("%s %.5f %.5f %.5f\n",n->name.data,n->node_to_world.cols[3].x,n->node_to_world.cols[3].y,n->node_to_world.cols[3].z);}if(t!=s)ufbx_free_scene(t);}ufbx_free_scene(s);return 0;}
